    p2: 'デプロイメントは、テンプレートをプロンプトのロール (System、Task、DelegatedTask など) に結び付けます。結び付けは最新版に追従するか、特定のバージョンに固定するため、本番のデプロイメントを変えずにテンプレートを編集し、好きなタイミングで切り替えられます。各実行は、使用したバージョンを正確に記録します。'
