    p2: 'デプロイメントは、エージェントが使うべきサーバーをそれぞれエイリアス付きで結び付けます。コンパイル時に Garrison はそれらをハーネスの MCP 設定に書き込み、ヘッダー内のシークレット参照を解決します。ワーカーは起動前に必須ツールを確認します。エージェントが委任できる場合は、Garrison 自身の MCP サーバーが自動的に追加されます。'
