    p2: 'デプロイメントはシークレットをエイリアスで結び付けます。ハーネスプロファイルの環境変数やファイルは {{secret.alias}} を参照するため、同じプロファイルをデプロイメントごとに異なるキーで使えます。値は実行のコンパイル時にのみ復号され、TLS でワーカーに送られ、ログからは除去されます。'
