  modelPrices: {"title": "モデル料金", "p1": "ハーネスが費用を報告しない場合の推定に使う、運用者設定の米ドル料金です。ゼロを含む報告済み費用が優先されます。", "p2": "無効な料金は使用しません。料金を編集または削除しても保存済みの実行費用は変わりません。"},
  usageQuotas: {"title": "使用量クォータ", "p1": "テナント、エージェント、デプロイメントの実行数、トークン数、既知の費用に対するUTC日次上限と現在の同時実行数です。", "p2": "空欄は無制限、ゼロは使用禁止です。日次カウンターはUTC午前0時にリセットされます。同時実行数は現在のアクティブ実行を数えます。 既定では無効です。有効にすると、設定した制限で実行を拒否し、対応するハーネスの予算を下げます。無効時は使用量の記録のみ行い、実行には影響しません。"},
