    p2: 'コントロールノードのうち 1 つがリーダーです。リーダーはデータベース内のリースを保持し、クラスター全体のメンテナンスを行います: 保持期間に基づくクリーンアップ、応答のないレプリカのオフライン化、古い行の削除です。リーダーが停止すると、数秒以内に別のレプリカがリースを引き継ぎます。',
    p3: 'ワーカーノード (ワーカーノードタブ) は残りの半分を担います: コントロールプレーンからリースされた実行を取得し、ハーネスを実行します。コントロールノードがハーネスを実行することはなく、ワーカーがデータベースに触れることもありません。各レプリカは自分自身を登録し 5 秒ごとにハートビートを送信するため、このタブは読み取り専用です。'
