    p2: 'キュータブには、待機中の同じ実行が表示されます。キュー待ちの実行には適切なハーネスと配置を持つノードが必要で、割り当て済みの実行は確保済み、実行中の実行は処理中です。キューに長く留まる実行は、容量不足か、どのノードにも一致しない配置ルールを示しています。'
