    p2: '1 つのハーネスでキュー待ちの数が増え続ける場合、通常は、そのハーネスを通知している準備完了のノードがない、一致するノードが満杯である、またはデプロイメントがどのノードも持たないプールやラベルを必須にしている、のいずれかです。'
