    p3: '平均値では、値を計測できなかった実行は除外されます。パーセンタイルは分布の裾を示し、p95 はこれより遅い実行が 20 件に 1 件だけであることを意味します。エージェントやハーネスでグループ化すると、それらを並べて比較できます。'
